    bg=cnt.most_common(1)[0][0]
    # anchors: cells whose value is not bg and not part of an existing multi-cell non-bg connected component? 
    # simpler: treat every non-bg non-marker cell? Instead: components of non-bg cells.
    seen=set(); comps=[]
    for r in range(H):
        for c in range(W):
            if inp[r][c]!=bg and (r,c) not in seen:
                stack=[(r,c)]; comp=[]; seen.add((r,c))
                while stack:
                    a,b=stack.pop(); comp.append((a,b))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            x,y=a+dr,b+dc
                            if 0<=x<H and 0<=y<W and inp[x][y]!=bg and (x,y) not in seen:
                                seen.add((x,y)); stack.append((x,y))
                comps.append(comp)
    # multi-cell comps (existing clusters like 4/2 L) unchanged; single cells get decorations
    dec={'2':'4_shape_down_left','3':''}
    info={2:(('4',((-1,-1),(0,-1),(1,-1),(1,0)))), 3:(('7' if bg==8 else '6',[(1,1)] if bg==0 else [(1,0)]))}
    # adjust: bg0 case decor=6 at (+1,+1); bg8 case decor=7 at (+1,0)
    decor={(2,8):'4',(2,0):'4',(3,8):'7',(3,0):'6'}
    for comp in comps:
        if len(comp)>1: continue
        val=g[comp[0][0]][comp[0][1]]
        key=(val,bg)
        if key not in info: continue
        dcol,offs=info[key]
        for dr,dc in offs:
            r,c=comp[0][0]+dr,comp[0][1]+dc
            if 0<=r<H and 0<=c<W and g[r][c]==bg:
                g[r][c]=dcol
    return g
