    H,W=len(inp),len(inp[0]); seen=set(); out=[]
    for r in range(H):
        for c in range(W):
            if inp[r][c]!=bg and (r,c) not in seen:
                st=[(r,c)]; cc=[]; seen.add((r,c))
                while st:
                    a,b=st.pop(); cc.append((a,b))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
