def transforms(rel):
    res={}
    cur=list(rel)
    def ro90(p): return (p[1],-p[0])
    for k in range(4):
        res['R%02d'%k]=list(cur)
        res['R%02dM'%((k*10+1)%100)]=[(b,a) for a,b in cur]
        res['R%02dM2'%((k*10+2)%100)]=[]
        break
    # redo cleanly
    res={}; cur=list(rel); seen_set=set()
    for k in range(4):
        seen_set.clear(); 
        variants=[cur[:],[(b,a) for a,b in cur],[(-b,-a) for a,b in cur],[(a,-b) for a,b in cur]]
        names=['id','H-flip','rot180','V-flip']
        for j,v in enumerate(variants):
            base=[]
            ok=True
            for p in v:
                q=(p[0]+min(a for a,b in rel),p[1]+min(b for a,b in rel))
                if not (0<=q[0]<max(a for a,b in rel)-min(a for a,b in rel)+1 and 0<=q[1]<max(b for a,b in rel)-min(b for a,b in rel)+1):
                    ok=False;break
                base.append(q)
            res[names[j]+'R%d'%(k)] = base
        cur=[ro90(p) for p in cur]
    return res

