def comps_of(gi,bg):
    H,W=len(gi),len(gi[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for r in range(H):
        for c in range(W):
            if gi[r][c]!=bg and not seen[r][c]:
                st=[(r,c)]; comp=set(); seen[r][c]=True
                while st:
                    p=st.pop(); comp.add(p)
                    for a,b_ in ((p[0]+1,p[1]),(p[0]-1,p[1]),(p[0],p[1]+1),(p[0],p[1]-1)):
                        if 0<=a<H and 0<=b_<W and gi[a][b_]!=bg and not seen[a][b_]:
                            seen[a][b_]=True; st.append((a,b_))
                out.append(comp)
    return out

