def comps_of(g,bg):
    R,C=len(g),len(g[0]); seen=set(); out=[]
    for r in range(R):
        for c in range(C):
            if g[r][c]==bg or (r,c) in seen: continue
            st=[(r,c)]; seen.add((r,c)); comp=[]
            while st:
                y,x=st.pop(); comp.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<R and 0<=nx<C and g[ny][nx]!=bg and (ny,nx) not in seen:
                        seen.add((ny,nx)); st.append((ny,nx))
            out.append(comp)
    return out
